// Data API: list {{integer:limit}} records from the {{php:resource}} layout
$result = $bridge->getRecords([
    '_limit' => {{integer:limit}},
    '_offset' => 1,
]);

php:odata.template:
// OData: list {{integer:limit}} records from the {{php:resource}} table
$result = $bridge->listODataRecords([
    'table' => '{{php:resource}}',
    'top' => {{integer:limit}},
    'count' => true,
