javascript:data-api.template:
// Browser-safe read: ask the protected PHP bridge to list records through the Data API.
const response = await fetch('/openbridge-api.php', {
  method: 'POST',
  credentials: 'include',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    action: 'playground',
    transport: 'data-api',
    operation: 'list',
    resource: {{js:resource}},
    limit: {{integer:limit}},
  }),
});

const result = await response.json();

